package local.my0511.lite;
import android.content.*;
import android.os.*;
import android.webkit.*;
import android.net.http.SslError;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
/** Sole foreground/background submitter. Main-looper ownership; uncertain submissions never retry. */
public final class PublishEngine {
 private final Context context;private final TaskStore store;private final SharedPreferences prefs;
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private final ForumClient client=new ForumClient();
 private static final class Hold extends IOException {Hold(){super("最后一楼是当前账户，防连帖暂缓15分钟");}}
 private String progress="尚未开始执行",phase="idle";private long began=0;private int revision=0;
 public String progress(){return progress+(busy()?" · 已用 "+Math.max(0,(System.currentTimeMillis()-began)/1000)+" 秒（最长90秒）":"");}
 public int revision(){return revision;}
 public String phase(){return phase;}
 private void stage(String code,String message){phase=code;progress=message;revision++;if(active!=null){active.note=message;try{store.save();}catch(Exception e){prefs.edit().putBoolean("queueEnabled",false).commit();}}}
 public void reportBlocked(String reason){stage("blocked",reason);}
 public void reportPaused(String reason){if(!busy())stage("paused",reason);}
 private boolean reject(String reason){stage("blocked",reason);log("未开始 · "+reason);return false;}
 private WebView view;private Task active;private int generation;private boolean preparing,polling;private long baseline;private Set<String> known=new HashSet<>();private Runnable completion;private Object owner;
 public PublishEngine(Context c,TaskStore s){context=c;store=s;prefs=c.getSharedPreferences("settings",0);}
 public boolean busy(){return active!=null;}
 public PublishRules rules(){PublishRules r=new PublishRules();r.minMinutes=prefs.getInt("gap",10);r.meanMinutes=prefs.getInt("mean",r.minMinutes);r.daily=prefs.getInt("daily",3);r.start=prefs.getInt("start",540);r.end=prefs.getInt("end",1350);r.perThread=prefs.getInt("perThread",2);r.quietDays=prefs.getInt("quiet",0);r.validate();return r;}
 private String key(Task t){return "G.account."+t.accountId+".";}
 private String day(){return PublishRules.day(System.currentTimeMillis());}
 private int today(Task t){return day().equals(prefs.getString(key(t)+"day",""))?prefs.getInt(key(t)+"sent",0):0;}
 private String threadKey(Task t){return key(t)+"thread."+day()+"."+t.tid;}
 private String block(Task t){return rules().blocked(t,t.accountId,System.currentTimeMillis(),prefs.getLong(key(t)+"lastAttempt",0),today(t),prefs.getInt(threadKey(t),0));}
 public void log(String note){String all=java.time.Instant.now().atZone(PublishRules.ZONE).toLocalDateTime()+" · "+note+"\n"+prefs.getString("G.logs","");String[] lines=all.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(300,lines.length);i++)b.append(lines[i]).append('\n');prefs.edit().putString("G.logs",b.toString()).commit();}
 public boolean start(Task t,Object token,Runnable done){if(Looper.myLooper()!=Looper.getMainLooper())throw new IllegalStateException("Main looper required");if(busy())return false;if(!prefs.getBoolean("queueEnabled",false))return reject("执行开关未开启，尚未发送");try{t.validate();if(t.accountId.isEmpty()||t.accountName.isEmpty())throw new IOException("任务尚未绑定账户");String why=block(t);if(!why.isEmpty())return reject(why+"；尚未发送");t.preparing();store.save();}catch(Exception e){t.interrupted();try{store.save();}catch(Exception ignored){}prefs.edit().putBoolean("queueEnabled",false).commit();return reject("准备失败："+e.getMessage()+"；尚未发送");}active=t;owner=token;completion=done;preparing=false;polling=false;baseline=0;known.clear();began=System.currentTimeMillis();stage("identity","正在连接论坛，核对实际账户（尚未提交）");int gen=++generation;String cookies=CookieManager.getInstance().getCookie(ForumPolicy.BASE);handler.postDelayed(()->{if(gen==generation&&busy())fail("执行超时，请核实任务");},90000);
  io.execute(()->{try{String html=client.get(ForumPolicy.board(1),cookies,null);SessionInfo session=SessionInfo.parseForum(html);if(session.state!=SessionInfo.State.LOGGED_IN||!t.accountId.equals(session.uid)||!t.accountName.equals(session.nickname))throw new IOException("实际论坛账户与任务不一致，请重新登录核对");handler.post(()->{if(gen==generation&&active==t)stage("baseline","账户核对完成，正在读取目标帖子及末楼（尚未提交）");});long before=0;Set<String> ids=new HashSet<>();if(t.reply){String url=ForumPolicy.thread(t.tid,1);ForumParser.Page p=ForumParser.thread(client.get(url,cookies,null),url);url=ForumPolicy.thread(t.tid,p.totalPages);if(p.totalPages>1)p=ForumParser.thread(client.get(url,cookies,null),url);if(p.floors.isEmpty())throw new IOException("未取得楼层基线");if(prefs.getBoolean("noConsecutive",true)&&p.floors.get(p.floors.size()-1).author.equals(t.accountName))throw new Hold();for(ForumParser.Floor f:p.floors)if(ForumPolicy.digits(f.pid))before=Math.max(before,Long.parseLong(f.pid));if(before==0)throw new IOException("楼层标识不完整");}else{List<ForumParser.Topic> topics=ForumParser.board(html,ForumPolicy.board(1));if(topics.isEmpty())throw new IOException("未取得主题基线");for(ForumParser.Topic topic:topics)ids.add(topic.tid);}final long pid=before;handler.post(()->{if(gen!=generation||active!=t)return;baseline=pid;known.addAll(ids);load(t,gen);});}catch(Exception e){handler.post(()->{if(gen==generation){if(e instanceof Hold)hold();else fail(e.getMessage());}});}});return true;
 }
 private String safeWebsiteMessage(String value){if(value==null)return "请打开官方表单查看";String plain=value.replaceAll("https?://[^\\s]+","[链接已省略]").replaceAll("[\\p{Cntrl}&&[^\\n\\t]]","").trim();String lower=plain.toLowerCase(java.util.Locale.ROOT);if(lower.contains("formhash")||lower.contains("cookie")||lower.contains("token")||plain.contains("密码"))return "包含敏感字段，详情请在官方表单查看";return plain.length()>180?plain.substring(0,180)+"…":plain;}
 private String asset(String name)throws Exception{try(InputStream in=context.getAssets().open(name)){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);return new String(b.toByteArray(),StandardCharsets.UTF_8);}}
 private JSONObject args(Task t)throws Exception{return new JSONObject().put("reply",t.reply).put("tid",t.tid).put("title",t.title).put("message",t.message).put("author",t.accountName).put("uid",t.accountId).put("typeId",t.typeId);}
 private void load(Task t,int gen){if(!block(t).isEmpty()){fail(block(t));return;}stage("form","正在加载官方发帖表单（尚未提交）");view=new WebView(context);WebSettings s=view.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setUserAgentString(ForumClient.UA);s.setGeolocationEnabled(false);s.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptThirdPartyCookies(view,false);view.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsAlert(WebView v,String url,String message,JsResult result){result.cancel();if(gen==generation)fail("网站提示："+safeWebsiteMessage(message));return true;}@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public boolean onShowFileChooser(WebView v,ValueCallback<android.net.Uri[]> cb,FileChooserParams p){cb.onReceiveValue(null);return true;}});view.setWebViewClient(new WebViewClient(){
  @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !ForumPolicy.webMainAllowed(r.getUrl().toString());}
  @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){String u=r.getUrl().toString();return (r.isForMainFrame()?ForumPolicy.webMainAllowed(u):ForumPolicy.resourceAllowed(u))?null:new WebResourceResponse("text/plain","UTF-8",403,"Blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
  @Override public void onReceivedSslError(WebView v,SslErrorHandler h,SslError e){h.cancel();if(gen==generation)fail("证书校验失败");}
  @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame()&&gen==generation)fail("发布页面连接失败");}
  @Override public void onReceivedHttpError(WebView v,WebResourceRequest r,WebResourceResponse response){if(r.isForMainFrame()&&gen==generation)fail("发布页面返回HTTP "+response.getStatusCode()+"，已停止");}
  @Override public void onPageFinished(WebView v,String u){if(gen!=generation||active!=t)return;CookieManager.getInstance().flush();if(t.state==Task.State.PREPARING&&!preparing&&ForumPolicy.postingPage(u,t)){preparing=true;handler.postDelayed(()->prepare(t,gen),700);}else if(t.state==Task.State.SUBMIT_INTENT)poll(t,gen);else if(t.state==Task.State.PREPARING&&!ForumPolicy.postingPage(u,t))fail("未进入预期发帖表单，可能需要重新登录或人工验证");}
 });view.loadUrl(ForumPolicy.post(t));}
 private boolean live(Task t,int gen){return active==t&&generation==gen&&prefs.getBoolean("queueEnabled",false);}
 private void prepare(Task t,int gen){if(!live(t,gen))return;stage("editor","正在同步编辑器并核对正文（尚未提交）");try{view.evaluateJavascript(asset("editor.js")+"\n"+asset("prepare.js")+"("+args(t)+")",raw->{if(!live(t,gen))return;try{JSONObject result=new JSONObject(raw);if(!"ready".equals(result.optString("status")))throw new IOException(result.optString("note","未能准备表单"));String why=block(t);if(!why.isEmpty())throw new IOException(why);stage("intent","表单已核对，正在保存提交意图");t.intent();store.save();if(!prefs.edit().putString(key(t)+"day",day()).putInt(key(t)+"sent",today(t)+1).putLong(key(t)+"lastAttempt",System.currentTimeMillis()).putInt(threadKey(t),prefs.getInt(threadKey(t),0)+1).commit())throw new IOException("发布计数无法保存");if(!live(t,gen)){fail("提交前暂停");return;}stage("submitting","正在点击发表，结果尚未确认；请勿重复操作");log("提交意图落盘 · "+t.id);view.evaluateJavascript(asset("submit.js")+"("+args(t)+")",clicked->{if(gen!=generation||active!=t)return;if(!"true".equals(clicked)){fail("点击结果不确定，须人工核实");return;}stage("receipt","已触发发表，正在等待论坛回执；尚不能认定成功");handler.postDelayed(()->poll(t,gen),1800);});}catch(Exception e){fail(e.getMessage());}});}catch(Exception e){fail("无法准备发布");}}
 private void poll(Task t,int gen){if(!live(t,gen)||polling)return;String url=view.getUrl();if(url==null||!ForumPolicy.readAllowed(url)||ForumPolicy.threadId(url).isEmpty()){polling=true;view.evaluateJavascript("(function(){var nodes=document.querySelectorAll('#fwin_dialog .alert_error,#fwin_dialog .alert_info,#messagetext,#return_message,.alert_error');for(var i=0;i<nodes.length;i++){var n=nodes[i];if(n.getClientRects().length&&n.innerText.trim())return n.innerText.trim().slice(0,300);}return '';})()",raw->{polling=false;if(!live(t,gen))return;try{String message=new JSONArray("["+raw+"]").optString(0,"");if(!message.isEmpty()){fail("网站尚未确认发表："+safeWebsiteMessage(message));return;}}catch(Exception ignored){}handler.postDelayed(()->poll(t,gen),1500);});return;}polling=true;view.evaluateJavascript("(function(){return {url:location.href,html:document.documentElement.outerHTML.slice(0,3000000)};})()",raw->{polling=false;if(!live(t,gen))return;try{JSONObject j=new JSONObject(raw);String u=j.getString("url");if(!ForumPolicy.readAllowed(u))throw new IOException();ForumParser.Page p=ForumParser.thread(j.getString("html"),u);Set<String> old=new HashSet<>();for(ForumParser.Floor f:p.floors)if(ForumPolicy.digits(f.pid)&&Long.parseLong(f.pid)<=baseline)old.add(f.pid);String receipt=t.reply?ForumParser.receipt(p,t,t.accountName,old):known.contains(ForumPolicy.threadId(u))?"":ForumParser.receipt(p,t,t.accountName,Collections.emptySet());if(!receipt.isEmpty()){t.receipt=receipt;t.state=Task.State.DONE;t.note="回执匹配账户、内容和新楼层";store.save();stage("done","发表成功：已取得匹配账户、正文和新楼层的回执");log("回执确认 · "+t.id);finish();}else handler.postDelayed(()->poll(t,gen),1800);}catch(Exception e){fail("无法核实发布回执");}});}
 public void cancel(Object token,String reason){if(busy()&&(token==null||owner==token))fail(reason);}
 private void hold(){if(active==null)return;active.state=Task.State.READY;active.holdUntil=System.currentTimeMillis()+15*60000L;active.note="防连帖暂缓，15分钟后重新核对末楼；不会消耗发布计数";try{store.save();stage("held",active.note);log("防连帖暂缓 · "+active.id);finish();}catch(Exception e){fail("暂缓状态保存失败");}}
 private void fail(String reason){if(active==null)return;active.interrupted();active.note=reason+(active.state==Task.State.NEEDS_REVIEW?"；可能已发出，不会自动重发":"；未触发提交，请处理后重审");try{store.save();}catch(Exception e){log("任务状态保存失败，禁止继续发布");}prefs.edit().putBoolean("queueEnabled",false).commit();stage(active.state==Task.State.NEEDS_REVIEW?"review":"failed",active.note);log("已暂停 · "+reason);finish();}
 private void finish(){generation++;active=null;owner=null;handler.removeCallbacksAndMessages(null);if(view!=null){view.stopLoading();view.destroy();view=null;}Runnable done=completion;completion=null;if(done!=null)done.run();}
}
